/* ПЕРСОНАЛЬНЫЕ ДАННЫЕ: найти и обезличить — в таблице и в документе.
   Ищет телефоны, e-mail, СНИЛС и ИНН физлиц (с проверкой контрольных чисел), номера карт
   (алгоритм Луна), счета физлиц, паспорта, даты рождения, ФИО и адреса с квартирой.
   В таблице узнаёт и столбцы по заголовкам («ФИО», «Телефон», «Дата рождения»…).
   Отчёт — только количества и места, без самих значений: найденное не уходит ни в журнал,
   ни в хранилище плагина, ни в сеть (сети у плагина нет). Обезличивание — маска, условный
   код или удаление; в таблице — одной операцией, которую отменяет Ctrl+Z. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

const вДокументе = typeof документ !== 'undefined';
const Б = 'А-Яа-яЁёA-Za-z0-9';
const ВИДЫ = [
  {ключ: 'телефон', имя: 'Телефоны', код: 'Тел'},
  {ключ: 'email', имя: 'E-mail', код: 'Почта'},
  {ключ: 'снилс', имя: 'СНИЛС', код: 'СНИЛС'},
  {ключ: 'инн', имя: 'ИНН физлиц', код: 'ИНН'},
  {ключ: 'карта', имя: 'Номера карт', код: 'Карта'},
  {ключ: 'счёт', имя: 'Счета физлиц', код: 'Счёт'},
  {ключ: 'паспорт', имя: 'Паспорта', код: 'Паспорт'},
  {ключ: 'рождение', имя: 'Даты рождения', код: 'ДР'},
  {ключ: 'фио', имя: 'ФИО', код: 'Субъект'},
  {ключ: 'адрес', имя: 'Адреса', код: 'Адрес'},
];
const цифры = s => String(s).replace(/\D/g, '');
/* контрольные числа */
function снилсВерен(s){
  const ц = цифры(s); if(ц.length !== 11) return false;
  const номер = ц.slice(0, 9), к = +ц.slice(9);
  if(+номер <= 1001998) return false;                     /* до 001-001-998 контрольное число не считают */
  let сумма = 0; for(let i = 0; i < 9; i++) сумма += +номер[i] * (9 - i);
  let ж = сумма < 100 ? сумма : сумма === 100 || сумма === 101 ? 0 : сумма % 101; if(ж === 100) ж = 0;
  return ж === к;
}
function иннФЛВерен(s){
  const ц = цифры(s); if(ц.length !== 12) return false;
  const к = (веса, n) => (веса.reduce((a, w, i) => a + w * +ц[i], 0) % 11) % 10 === +ц[n];
  return к([7, 2, 4, 10, 3, 5, 9, 4, 6, 8], 10) && к([3, 7, 2, 4, 10, 3, 5, 9, 4, 6, 8], 11);
}
function луна(s){
  const ц = цифры(s); if(ц.length < 13 || ц.length > 19 || !/^[2-6]/.test(ц)) return false;
  let сумма = 0;
  for(let i = 0; i < ц.length; i++){ let d = +ц[ц.length - 1 - i]; if(i % 2){ d *= 2; if(d > 9) d -= 9; } сумма += d; }
  return сумма % 10 === 0;
}
/* шаблоны: регулярное выражение и проверка совпадения */
const ШАБЛОНЫ = [
  {вид: 'email', re: /[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}/g},
  {вид: 'карта', re: /(?<![\d])(?:\d[ \-]?){12,18}\d(?![\d])/g, если: луна},
  {вид: 'счёт', re: /(?<![\d])(?:40817|40820|4230[1-7])\d{15}(?![\d])/g},
  {вид: 'снилс', re: /(?<![\d])\d{3}[ \-]?\d{3}[ \-]?\d{3}[ \-]?\d{2}(?![\d])/g, если: снилсВерен},
  {вид: 'инн', re: /(?<![\d])\d{12}(?![\d])/g, если: иннФЛВерен},
  {вид: 'телефон', re: /(?<![\d+])(?:\+7|8|7)[ \-(]{0,2}9\d{2}[ \-)]{0,2}\d{3}[ \-]?\d{2}[ \-]?\d{2}(?![\d])|(?<![\d+])(?:\+7|8)[ \-(]{0,2}\d{3,5}[ \-)]{0,2}\d{1,3}[ \-]?\d{2}[ \-]?\d{2}(?![\d])/g,
    если: s => цифры(s).length === 11},
  {вид: 'паспорт', re: new RegExp('паспорт[^\\d\\n]{0,25}(\\d{2} ?\\d{2})[ №]{0,3}(\\d{6})(?![\\d])', 'gi'), группа: true},
  {вид: 'паспорт', re: /(?<![\d])\d{2} \d{2} \d{6}(?![\d])/g},
  {вид: 'рождение', re: /(?:дата рождения|д\.\s?р\.|родил(?:ся|ась))[:\s]*\d{1,2}\.\d{1,2}\.\d{2,4}/gi},
  {вид: 'фио', re: new RegExp('[А-ЯЁ][а-яё]+(?:-[А-ЯЁ][а-яё]+)?\\s+[А-ЯЁ][а-яё]+\\s+[А-ЯЁ][а-яё]+(?:вич|вна|ична|инична|оглы|кызы)(?![' + Б + '])', 'g')},
  {вид: 'фио', re: new RegExp('(?<![' + Б + '])[А-ЯЁ][а-яё]{2,}(?:-[А-ЯЁ][а-яё]+)?\\s+[А-ЯЁ]\\.\\s?[А-ЯЁ]\\.', 'g')},
  {вид: 'адрес', re: /(?:ул\.|улица|пр-т|проспект|пер\.|переулок|ш\.|шоссе|б-р|бульвар|наб\.)\s*[А-ЯЁA-Z0-9][^\n;]{1,60}?(?:д\.|дом)\s*\d+[а-я]?(?:[^\n;]{0,20}?(?:кв\.|квартира)\s*\d+)/gi},
];
/* заголовки столбцов, весь столбец — этого вида */
const ЗАГОЛОВКИ = [
  [/^(фио|ф\.и\.о\.?|фамилия|имя|отчество|сотрудник|клиент|пациент|получатель|работник|физ.*лицо)/i, 'фио'],
  [/^(телефон|тел\.?|моб|мобильный|phone)/i, 'телефон'], [/^(e-?mail|почта|эл.*почта|электронная почта)/i, 'email'],
  [/^снилс/i, 'снилс'], [/^инн/i, 'инн'], [/^(паспорт|серия.*номер)/i, 'паспорт'],
  [/(дата рождения|д\.\s?р\.?$|^др$|birth)/i, 'рождение'], [/^(адрес|место жительства|регистрация|прописка)/i, 'адрес'],
  [/^(номер карты|карта)/i, 'карта'], [/^(счёт|счет|лицевой счёт|р\/с)/i, 'счёт'],
];
function найтиВТексте(т, виды){
  const out = [];
  for(const ш of ШАБЛОНЫ){
    if(!виды.has(ш.вид)) continue;
    ш.re.lastIndex = 0;
    let м;
    while((м = ш.re.exec(т))){
      const с = м[0];
      if(ш.если && !ш.если(с)) continue;
      /* не пересекаться с уже найденным (карта и СНИЛС, телефон и ИНН) */
      if(out.some(x => м.index < x.начало + x.длина && x.начало < м.index + с.length)) continue;
      out.push({вид: ш.вид, начало: м.index, длина: с.length, текст: с});
    }
  }
  return out.sort((a, b) => a.начало - b.начало);
}
/* как скрыть одно значение */
function скрыть(вид, с, режим, коды){
  if(режим === 'удалить') return '';
  if(режим === 'код'){
    const ключ = вид + '|' + с.toLowerCase().replace(/\s+/g, ' ');
    if(!коды.has(ключ)){ const n = [...коды.keys()].filter(k => k.startsWith(вид + '|')).length + 1; коды.set(ключ, ВИДЫ.find(x => x.ключ === вид).код + '-' + String(n).padStart(4, '0')); }
    return коды.get(ключ);
  }
  const ц = цифры(с);
  switch(вид){
    case 'телефон': return '+7 *** ***-**-' + ц.slice(-2);
    case 'email': { const [имя, домен] = с.split('@'); return имя[0] + '***@' + домен; }
    case 'снилс': return '***-***-*** **';
    case 'инн': return '**********' + ц.slice(-2);
    case 'карта': return '**** **** **** ' + ц.slice(-4);
    case 'счёт': return ц.slice(0, 5) + '***********' + ц.slice(-4);
    case 'паспорт': return с.replace(/\d{2} ?\d{2}[ №]{0,3}\d{6}$/, '** ** ******').replace(/^\d{2} \d{2} \d{6}$/, '** ** ******');
    case 'рождение': return с.replace(/\d{1,2}\.\d{1,2}\.(\d{2,4})/, '**.**.$1').replace(/^\d{1,2}\.\d{1,2}\.\d{2,4}$/, '**.**.****');
    case 'фио': { const ч = с.split(/\s+/).filter(Boolean); return ч.map(x => x[0] + '.').join(' '); }
    case 'адрес': return с.replace(/(д\.|дом)\s*\d+[а-я]?/i, '$1 *').replace(/(кв\.|квартира)\s*\d+/i, '$1 *').replace(/^((?:ул\.|улица|пр-т|проспект|пер\.|переулок|ш\.|шоссе|б-р|бульвар|наб\.)\s*)[^,]+/i, '$1***');
  }
  return '***';
}
function выбранныеВиды(п){ return new Set(ВИДЫ.filter(в => п['в_' + в.ключ] !== false).map(в => в.ключ)); }
const режимИз = п => String(п.режим || 'маска').startsWith('код') ? 'код' : String(п.режим || '').startsWith('удал') ? 'удалить' : 'маска';

/* ===== ТАБЛИЦЫ ===== */
async function областиДляОбхода(п){
  const охват = String(п.охват || 'этот лист');
  if(охват === 'выделение'){ const в = книга.выделение; return [{лист: в.лист, r1: в.r1 - 1, c1: в.c1 - 1, r2: в.r2 - 1, c2: в.c2 - 1}]; }
  const листы = охват === 'вся книга' ? книга.листы : [книга.выделение ? книга.выделение.лист : книга.листы[0]];
  const out = [];
  for(const имя of листы){
    let строк = 0, столбцов = 0;
    try { строк = лист(имя).строк; столбцов = лист(имя).столбцов; } catch(e){}
    if(строк > 0 && столбцов > 0) out.push({лист: имя, r1: 0, c1: 0, r2: строк - 1, c2: столбцов - 1});
  }
  return out;
}
const ПРЕДЕЛ_КЛЕТОК = 500000;
/* Обход: для каждой клетки — что в ней нашлось. Значения дальше этой функции не уходят. */
async function обойти(п, наКлетку){
  const виды = выбранныеВиды(п), области = await областиДляОбхода(п);
  let клеток = 0, урезано = false;
  for(const о of области){
    let r2 = о.r2;
    if((r2 - о.r1 + 1) * (о.c2 - о.c1 + 1) + клеток > ПРЕДЕЛ_КЛЕТОК){ r2 = о.r1 + Math.max(0, Math.floor((ПРЕДЕЛ_КЛЕТОК - клеток) / (о.c2 - о.c1 + 1))) - 1; урезано = true; }
    if(r2 < о.r1) continue;
    const строки = await лист(о.лист).прочитать(ОБЛАСТЬ(о.r1, о.c1, r2, о.c2), {формулы: true});
    клеток += (r2 - о.r1 + 1) * (о.c2 - о.c1 + 1);
    /* заголовки: первая строка области с текстом */
    const столбцыВида = {};
    const шапка = (строки[0] || []);
    шапка.forEach((v, j) => { if(typeof v !== 'string') return; for(const [re, вид] of ЗАГОЛОВКИ) if(re.test(v.trim()) && виды.has(вид)){ столбцыВида[j] = вид; break; } });
    const естьШапка = Object.keys(столбцыВида).length > 0;
    строки.forEach((ряд, i) => (ряд || []).forEach((v, j) => {
      if(v === null || v === undefined || v === '' || typeof v === 'boolean') return;
      const r = о.r1 + i, c = о.c1 + j;
      if(i === 0 && естьШапка) return;
      let формула = null;
      try { формула = лист(о.лист).ячейка(r + 1, c + 1).формула; } catch(e){}
      if(формула) return;                                    /* формулы не трогаем: они считаются из других клеток */
      const т = typeof v === 'number' ? (Number.isInteger(v) ? String(v) : '') : String(v);
      if(!т) return;
      let находки = найтиВТексте(т, виды);
      const видСтолбца = столбцыВида[j];
      if(видСтолбца && !находки.some(x => x.вид === видСтолбца) && похоже(видСтолбца, т, v)) находки = [{вид: видСтолбца, начало: 0, длина: т.length, текст: т, поЗаголовку: true}];
      if(находки.length) наКлетку(о.лист, r, c, т, находки);
    }));
  }
  return {урезано};
}
/* значение в столбце «ФИО», «Телефон»… — правда ли похоже на такие данные («Итого» — не ФИО) */
function похоже(вид, т, v){
  const ц = цифры(т).length;
  switch(вид){
    case 'фио': return /^[А-ЯЁA-Z][а-яёa-z]+(?:-[А-ЯЁ][а-яё]+)?(?:\s+[А-ЯЁA-Z][а-яёa-z]*\.?){1,3}$/.test(т.trim()) && !/^(итого|всего|сумма|итог)/i.test(т.trim());
    case 'телефон': return ц >= 10 && ц <= 12;
    case 'email': return т.includes('@');
    case 'рождение': return typeof v === 'number' ? v > 1000 && v < 80000 : /\d{1,2}[.\/-]\d{1,2}[.\/-]\d{2,4}/.test(т);
    case 'паспорт': return ц === 10;
    case 'снилс': return ц === 11;
    case 'инн': return ц === 12;
    case 'карта': return ц >= 13 && ц <= 19;
    case 'счёт': return ц === 20;
    case 'адрес': return т.trim().length > 6 && /\d/.test(т);
  }
  return false;
}
async function НайтиТаблица(){
  const п = параметры({});
  const сколько = {}, где = {};
  const {урезано} = await обойти(п, (имя, r, c, т, находки) => {
    for(const н of находки){
      сколько[н.вид] = (сколько[н.вид] || 0) + 1;
      const м = (где[н.вид] = где[н.вид] || new Map()), ключ = имя + '!' + БУКВА(c);
      м.set(ключ, (м.get(ключ) || 0) + 1);
    }
  });
  const ряды = ВИДЫ.filter(в => сколько[в.ключ]).map(в => [в.имя + ': ' + сколько[в.ключ],
    [...где[в.ключ].entries()].sort((a, b) => b[1] - a[1]).slice(0, 4).map(([к, n]) => к + ' (' + n + ')').join(', ')]);
  панель.список('отчёт', ряды.length ? ряды : [['Ничего не найдено', '']]);
  const всего = Object.values(сколько).reduce((a, b) => a + b, 0);
  панель.сообщение(всего ? 'Найдено ' + всего + ' значений с персональными данными. Это оценка: проверьте глазами — бывают и пропуски, и ложные срабатывания.'
    + (урезано ? ' Просмотрено только первые ' + ПРЕДЕЛ_КЛЕТОК.toLocaleString('ru-RU') + ' клеток.' : '') : 'Персональных данных не нашлось' + (урезано ? ' в первых ' + ПРЕДЕЛ_КЛЕТОК.toLocaleString('ru-RU') + ' клетках.' : '.'));
}
async function ОбезличитьТаблица(){
  const п = параметры({}), режим = режимИз(п);
  if(!(await диалог.вопрос('Обезличивание меняет данные прямо в книге (' + режим + '). Сначала сохраните копию: Файл → Сохранить как. Копия сохранена — продолжаем? Отменить можно и потом: Ctrl+Z отменяет всё одним шагом.'))) return;
  const коды = new Map();
  const правки = [];
  await обойти(п, (имя, r, c, т, находки) => {
    let нов = '', поз = 0;
    for(const н of находки){ нов += т.slice(поз, н.начало) + скрыть(н.вид, н.текст, режим, коды); поз = н.начало + н.длина; }
    нов += т.slice(поз);
    правки.push([имя, r, c, нов, находки.length]);
  });
  for(const [имя, r, c, нов] of правки) лист(имя).ячейка(r + 1, c + 1).значение = нов;
  const значений = правки.reduce((a, x) => a + x[4], 0);
  панель.сообщение(правки.length ? 'Обезличено ' + значений + ' значений в ' + правки.length + ' клетках (' + режим + ').' + (режим === 'код' ? ' Таблица «код ↔ значение» нигде не сохраняется.' : '') : 'Нечего обезличивать.');
  if(правки.length) панель.список('отчёт', [['Готово', значений + ' значений, ' + правки.length + ' клеток']]);
}

/* ===== ДОКУМЕНТЫ ===== */
let находкиДок = [];
function НайтиДок(){
  const п = параметры({}), виды = выбранныеВиды(п);
  находкиДок = [];
  документ.блоки.forEach((б, i) => { for(const н of найтиВТексте(String(б.текст || ''), виды)) находкиДок.push(Object.assign({блок: i}, н)); });
  const сколько = {};
  for(const н of находкиДок) сколько[н.вид] = (сколько[н.вид] || 0) + 1;
  const ряды = ВИДЫ.filter(в => сколько[в.ключ]).map(в => {
    const абзацы = [...new Set(находкиДок.filter(н => н.вид === в.ключ).map(н => н.блок + 1))];
    return [в.имя + ': ' + сколько[в.ключ], 'абзацы ' + абзацы.slice(0, 6).join(', ') + (абзацы.length > 6 ? '…' : '')];
  });
  панель.список('отчёт', ряды.length ? ряды : [['Ничего не найдено', '']]);
  панель.сообщение(находкиДок.length ? 'Найдено ' + находкиДок.length + ' значений с персональными данными. «К первой находке» — перейти к ней в тексте.' : 'Персональных данных не нашлось.');
}
function КПервой(){
  if(!вДокументе){ панель.сообщение('Переход по находкам — в документах.'); return; }
  if(!находкиДок.length) НайтиДок();
  if(!находкиДок.length) return;
  документ.перейти(находкиДок[0].блок);
}
const эк = т => String(т).replace(/[&<>]/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;'}[c]));
async function ОбезличитьДок(){
  const п = параметры({}), режим = режимИз(п), виды = выбранныеВиды(п);
  if(!(await диалог.вопрос('Обезличивание меняет текст документа (' + режим + '). Сначала сохраните копию: Файл → Сохранить как. Копия сохранена — продолжаем?'))) return;
  const коды = new Map();
  let значений = 0, абзацев = 0, безОформления = 0;
  документ.блоки.forEach((б, i) => {
    const т = String(б.текст || ''), находки = найтиВТексте(т, виды);
    if(!находки.length) return;
    /* правим текст внутри разметки, не трогая теги; если находка разрезана тегом — правим абзац целиком текстом */
    const html = String(б.html || '');
    const куски = html.split(/(<[^>]+>)/);
    let нашлиВHtml = 0;
    const новыйHtml = куски.map(к => {
      if(к.startsWith('<')) return к;
      const текст = к.replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
      const н = найтиВТексте(текст, виды);
      if(!н.length) return к;
      нашлиВHtml += н.length;
      let нов = '', поз = 0;
      for(const x of н){ нов += текст.slice(поз, x.начало) + скрыть(x.вид, x.текст, режим, коды); поз = x.начало + x.длина; }
      return эк(нов + текст.slice(поз));
    }).join('');
    if(нашлиВHtml >= находки.length) документ.правитьБлок(i, {html: новыйHtml});
    else {
      let нов = '', поз = 0;
      for(const x of находки){ нов += т.slice(поз, x.начало) + скрыть(x.вид, x.текст, режим, коды); поз = x.начало + x.длина; }
      документ.правитьБлок(i, {текст: нов + т.slice(поз)});
      безОформления++;
    }
    значений += находки.length; абзацев++;
  });
  находкиДок = [];
  панель.список('отчёт', [['Готово', значений + ' значений в ' + абзацев + ' абзацах']]);
  панель.сообщение(значений ? 'Обезличено ' + значений + ' значений в ' + абзацах(абзацев) + '.' + (безОформления ? ' В ' + абзацах(безОформления) + ' оформление внутри абзаца снято: находка была разрезана оформлением.' : '') : 'Нечего обезличивать.');
}
const абзацах = n => n + ' ' + (n % 10 === 1 && n % 100 !== 11 ? 'абзаце' : 'абзацах');

